import{_ as d,A as r,o as s,c,j as t,a,C as n,X as i}from"./chunks/framework.Bo638KvF.js";const y=JSON.parse('{"title":"Plans and costs: opt","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-opt.md","filePath":"reference-opt.md"}'),l={name:"rust/api/reference-opt.md"};function h(p,e,u,m,f,b){const o=r("DocChoices");return s(),c("div",null,[e[0]||(e[0]=t("h1",{id:"plans-and-costs-opt",tabindex:"-1"},[a("Plans and costs: opt "),t("a",{class:"header-anchor",href:"#plans-and-costs-opt","aria-label":'Permalink to "Plans and costs: opt"'},"​")],-1)),e[1]||(e[1]=t("p",null,[t("code",null,"cellpack::opt"),a(" represents cache residency, compiler options, machine costs, modeled loads and serial reference policies. The application's bound "),t("code",null,"Loader"),a(" supplies the graph and high-level compilation entry points. The runtime executes the resulting plan. Online compilation makes decisions ahead of the workers, rather than on each worker cache lookup. For a complete program and mode selection, use the "),t("a",{href:"/CellPack/rust/docs/planning.html"},"cache planning guide"),a(".")],-1)),n(o,{title:"Look up the contract you need",items:[{label:"PlanOptions",when:"Configure compilation",detail:"Budget, objective, reuse gap, horizon and compiler resources.",href:"#planoptions"},{label:"Plan and Residency",when:"Inspect or persist a fixed schedule",detail:"Bound identity, frame assignments and compatibility checks.",href:"#plan-and-residency"},{label:"CostModel",when:"Price work for a machine",detail:"Resource capacities and per-operation core-second costs.",href:"#costmodel-and-resource-accounting"},{label:"PageTrace",when:"Compare with a serial page reference",detail:"Page-only optimum with bypass and its limited scope.",href:"#serial-page-reference"}]}),e[2]||(e[2]=i(`<h2 id="compilation-and-replay" tabindex="-1">Compilation and replay <a class="header-anchor" href="#compilation-and-replay" aria-label="Permalink to &quot;Compilation and replay&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Loader method</th><th>Input</th><th>Return / effect</th></tr></thead><tbody><tr><td><code>plan_options</code></td><td>Cache bytes</td><td>Options with loader-derived gap and default costs</td></tr><tr><td><code>compile</code></td><td>Stored <code>&amp;[CellId]</code>, options</td><td>Owned offline <code>Plan</code></td></tr><tr><td><code>replay</code></td><td>Plan and exact stored sequence</td><td><code>PlanSummary</code> without record loading</td></tr><tr><td><code>replay_with_cost</code></td><td>Same plus another cost model</td><td>Repriced summary, unchanged decisions</td></tr><tr><td><code>compile_online</code></td><td>Stored sequence, finite-horizon options</td><td>Collected plan and <code>OnlineStats</code></td></tr><tr><td><code>plan_online</code></td><td>General <code>Accesses</code>, options</td><td>Online compiler statistics without loading</td></tr><tr><td><code>online</code></td><td>Validated options</td><td><code>Planning::Online</code> for a run</td></tr></tbody></table><p>Offline plans require a stored sequence. Its length must be divisible by the schema count; each value is a global <code>CellId</code>. Online planning accepts computed <code>Accesses</code> with the same ordering and determinism requirements. A collected online Plan still binds to the exact stored sequence supplied to <code>compile_online</code>. Compiler thread count affects sharding and can affect decisions; scheduling order of the same compilation does not define the policy.</p><h2 id="planoptions" tabindex="-1">PlanOptions <a class="header-anchor" href="#planoptions" aria-label="Permalink to &quot;PlanOptions&quot;">​</a></h2><p><code>PlanOptions::new(cache_bytes, gap)</code> uses 16 compiler threads, the <code>Time</code> objective, no cost model, no rows or block merging, <code>Incremental</code> row policy, and no explicit horizon or chunk. <code>Loader::plan_options</code> additionally derives the gap from the loader and supplies an NVMe default model with one output-cost entry per schema. It is the usual starting point for a loader.</p><h3 id="units-and-validation" tabindex="-1">Units and validation <a class="header-anchor" href="#units-and-validation" aria-label="Permalink to &quot;Units and validation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Unit and accepted values</th></tr></thead><tbody><tr><td><code>cache_bytes</code></td><td>Bytes; usable frames are <code>cache_bytes / page_size</code>, at most <code>u32::MAX</code></td></tr><tr><td><code>gap</code></td><td>Positive slots; <code>gap × slot_cells × schemas</code> must be below <code>u32::MAX</code> accesses</td></tr><tr><td><code>horizon</code></td><td>Optional slots; when explicit, at least <code>gap</code></td></tr><tr><td><code>chunk</code></td><td>Optional positive accesses; None uses <code>DEFAULT_CHUNK = 16384</code></td></tr><tr><td><code>threads</code></td><td>Compiler count; the engine treats zero as one</td></tr><tr><td><code>cpus</code></td><td>Optional logical CPU IDs; empty inherits affinity, invalid or clamped CPU sets fail</td></tr><tr><td><code>block_pages</code></td><td>None or 2–128 pages; requires a cost model</td></tr></tbody></table><p>The execution window is in slots and cannot exceed the reuse gap. Unlike the options, <code>Plan::distance()</code> and <code>OnlineStats::{distance, horizon, chunk}</code> use accesses. A slot contains <code>slot_cells × schemas</code> accesses.</p><p>Offline compilation uses the whole sequence as its horizon. Online compilation starts from the configured horizon, or twice the source cell count times the schema count in accesses. It raises that value to at least <code>distance + chunk</code> and clips it to the sequence length (<code>max(1)</code> for an empty sequence). The returned OnlineStats reports this effective horizon.</p><h3 id="objectives-and-retained-objects" tabindex="-1">Objectives and retained objects <a class="header-anchor" href="#objectives-and-retained-objects" aria-label="Permalink to &quot;Objectives and retained objects&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Choice</th><th>Contract</th></tr></thead><tbody><tr><td><code>PlanObjective::Misses</code></td><td>Page-only miss objective; decoded-row caching is off</td></tr><tr><td><code>PlanObjective::Time</code></td><td>Minimize modeled time under declared costs</td></tr><tr><td><code>rows = true</code></td><td>Requires a cost model; row selection takes effect under <code>Time</code> with nonzero frame capacity</td></tr><tr><td><code>RowPolicy::Incremental</code></td><td>Online/offline reuse-interval decisions</td></tr><tr><td><code>RowPolicy::Global</code></td><td>Whole-sequence row reference; active row selection requires a stored slice and full-sequence horizon</td></tr><tr><td><code>block_pages</code></td><td>Optional merged admission size; requires costs</td></tr><tr><td><code>cache_bytes</code></td><td>Planned frame budget, not total RSS</td></tr></tbody></table><p>Under <code>Misses</code>, setting <code>rows = true</code> does not enable row caching. Without a cost model, setting rows or block merging is an error. Enabling row candidates does not guarantee row admission: they compete with pages for the same frame budget.</p><p>Rows retain stored dtype and standard ids. Their size includes decompressed payload and page rounding; a row can occupy noncontiguous frames. Row hits still gather, map and process the row. Process outputs are not cached.</p><h2 id="plan-and-residency" tabindex="-1">Plan and Residency <a class="header-anchor" href="#plan-and-residency" aria-label="Permalink to &quot;Plan and Residency&quot;">​</a></h2><p><code>Plan</code> contains immutable residency and frame assignments plus compatibility identities. <code>Residency</code> describes an <code>Object::Page</code> or <code>Object::Row</code>, its admission and last use, and assigned frame extent. <code>frames_of</code> resolves its frame list.</p><table tabindex="0"><thead><tr><th>Plan query</th><th>Meaning</th></tr></thead><tbody><tr><td><code>len / schemas / slot_cells</code></td><td>Access count / schema count / positions per slot</td></tr><tr><td><code>reuse_gap / distance</code></td><td>Reservation gap in slots / accesses</td></tr><tr><td><code>cache_bytes / cache_frames</code></td><td>Declared byte budget / usable whole-page frames</td></tr><tr><td><code>cost / summary</code></td><td>Optional model and compiled summary</td></tr><tr><td><code>residencies / frames_of</code></td><td>Immutable planned contents</td></tr><tr><td><code>write / open</code></td><td>Binary file persistence</td></tr><tr><td><code>to_bytes / from_bytes</code></td><td>Owned byte representation</td></tr></tbody></table><p><code>CPKPLAN1</code> plans bind to inputs, mappings, schemas, process identities, slot size and exact access contents. <code>prepare</code> and <code>replay</code> check compatibility against the actual loader and sequence. <code>open</code> and <code>from_bytes</code> read the plan representation; successful deserialization alone does not establish graph compatibility. A serialized plan is not a portable promise of identical throughput on different hardware. Keep process identities synchronized with callback/configuration changes.</p><h2 id="costmodel-and-resource-accounting" tabindex="-1">CostModel and resource accounting <a class="header-anchor" href="#costmodel-and-resource-accounting" aria-label="Permalink to &quot;CostModel and resource accounting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Describes</th></tr></thead><tbody><tr><td>Capacity</td><td>Physical worker cores, device IOPS/bandwidth, memory bandwidth, overlap share</td></tr><tr><td><code>InputCost</code></td><td>Per-record, per-element and cold-chunk decode work</td></tr><tr><td><code>RowCost</code></td><td>Per-payload-byte gather and row-admission work</td></tr><tr><td><code>OutputCost</code></td><td>Mapping, filling, processing and partial-row costs per schema</td></tr><tr><td><code>ProcessCost</code></td><td>Process-size bands ending at declared maximum elements</td></tr><tr><td><code>convert</code></td><td>Per-element cost per loader <code>Conversion</code> class</td></tr><tr><td><code>Loads</code></td><td>Requests, device bytes, core-seconds and memory traffic</td></tr><tr><td><code>Prices</code></td><td>Marginal values used to compare reuse candidates</td></tr></tbody></table><p>Operation costs use core-seconds; capacity converts them into modeled wall time. Output-cost order must match schema order. <code>seconds</code>, <code>service</code> and <code>prices</code> operate on a load vector; their outputs are model results, not measurements.</p><p>For loads <code>R</code> requests, <code>B</code> device bytes, <code>C</code> core-seconds and <code>M</code> memory bytes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>device = max(R / iops, B / bandwidth)</span></span>
<span class="line"><span>workers = C / cores</span></span>
<span class="line"><span>seconds = max(max(device, workers) + serial * min(device, workers),</span></span>
<span class="line"><span>              M / memory_bandwidth)</span></span></code></pre></div><p><code>service</code> returns the four independent service times in request, device-byte, core and memory order. <code>prices</code> assigns marginal seconds per load unit near the supplied workload; <code>Prices::value(loads)</code> values a change at those prices.</p><p>Compilation validates positive finite capacities, finite nonnegative operation costs, <code>serial</code> in <code>[0, 1]</code>, a positive <code>bucket</code>, and exactly one output entry per schema. Nonempty process-cost curves have increasing inclusive <code>max_elements</code> bounds ending at <code>u32::MAX</code>. Loading a standalone cost-model byte representation checks its encoding; graph-specific validation happens at compilation/replay.</p><p><code>CostModel::defaults</code> provides hardware-tier defaults; <code>opt::defaults::model</code> and <code>Tier</code> select those defaults explicitly. Calibration records are managed by the application. Binary <code>to_bytes/from_bytes</code> is available without Serde; optional <code>serde</code> adds structured serialization derives.</p><h3 id="read-summaries-without-mixing-evidence" tabindex="-1">Read summaries without mixing evidence <a class="header-anchor" href="#read-summaries-without-mixing-evidence" aria-label="Permalink to &quot;Read summaries without mixing evidence&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Result</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PlanSummary</code> counters</td><td>Serial action counts, including requests, reads, decode work and hits</td></tr><tr><td><code>peak_bytes</code></td><td>Maximum bytes retained in serial access order</td></tr><tr><td><code>concurrent_peak_bytes</code></td><td>Peak with each residency reserved from <code>start − distance</code></td></tr><tr><td><code>PlanSummary::seconds()</code></td><td>Sum of modeled time over four sequence quarters; zero without costs</td></tr><tr><td><code>OnlineStats::modeled_seconds</code></td><td>Modeled work of the published accesses; zero without costs</td></tr><tr><td><code>OnlineStats::compile_seconds / waiting_seconds</code></td><td>Measured compilation wall time excluding / measuring wait for plan-ring space</td></tr></tbody></table><p>Use <a href="/CellPack/rust/docs/profiling.html">statistics and profiling</a> for measured run counters and timing. Repricing a saved plan does not recalibrate it or change its decisions.</p><h2 id="serial-page-reference" tabindex="-1">Serial page reference <a class="header-anchor" href="#serial-page-reference" aria-label="Permalink to &quot;Serial page reference&quot;">​</a></h2><p><code>PageTrace::from_source</code> extracts page uses for a stored sequence; <code>from_pages</code> constructs a synthetic trace. <code>page_uses</code> and <code>distinct_pages</code> describe it; <code>optimum(capacity_pages)</code> returns a page-only <code>CacheSummary</code>.</p><p>This optimal reference has serial page semantics and bypass. It does not include decoded rows, concurrency reservation gaps, sharding, or finite lookahead. Do not describe every production page-and-row plan as globally optimal.</p><h2 id="complete-interface-index" tabindex="-1">Complete interface index <a class="header-anchor" href="#complete-interface-index" aria-label="Permalink to &quot;Complete interface index&quot;">​</a></h2><h3 id="re-exports" tabindex="-1">Re-exports <a class="header-anchor" href="#re-exports" aria-label="Permalink to &quot;Re-exports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-enum-Tier.html"><code>Tier</code></a></td><td>A class of storage, for its default device rates.</td></tr></tbody></table><h3 id="structs" tabindex="-1">Structs <a class="header-anchor" href="#structs" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-struct-CacheSummary.html"><code>CacheSummary</code></a></td><td>What a serial run of a trace did: its page uses, and the hits and misses a capacity produced.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-CostModel.html"><code>CostModel</code></a></td><td>The loader’s resources on one machine and the work it does per access, record, element, request and cached-row byte. Work is in core-seconds: seconds of one physical core (two workers sharing a core through SMT take it together).</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-InputCost.html"><code>InputCost</code></a></td><td>Decoding records: core-seconds per record, per stored element and per record whose chunk is cold.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-Loads.html"><code>Loads</code></a></td><td>What a window of accesses takes from each resource.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-OnlineStats.html"><code>OnlineStats</code></a></td><td>What an online compilation did.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-OutputCost.html"><code>OutputCost</code></a></td><td>What one output schema’s delivery costs, per element, per row and per call.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-PageTrace.html"><code>PageTrace</code></a></td><td>Canonical page requests: cells in access order, each cell’s pages in file order. This serial reference has no execution window, reuse-gap reservation or management cost.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-Plan.html"><code>Plan</code></a></td><td>A cache plan: the residencies a compilation chose, the frames they hold, and what they were compiled for.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-PlanOptions.html"><code>PlanOptions</code></a></td><td>What a compilation optimizes for: the budget, the reuse gap, the objective and the cost model of one loader on one machine.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-PlanSummary.html"><code>PlanSummary</code></a></td><td>The serial execution of a plan, as an independent replay counts it.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-Prices.html"><code>Prices</code></a></td><td>Marginal seconds of a window’s modeled time per unit of each load: the gradient of a smoothed T at the loads it was taken at. Saving loads x is worth prices.value(x) seconds.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-ProcessCost.html"><code>ProcessCost</code></a></td><td>One band of a process function’s size curve: the costs that hold for a row of up to max_elements elements.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-Residency.html"><code>Residency</code></a></td><td>One residency: an object held from its admission through its last use.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-struct-RowCost.html"><code>RowCost</code></a></td><td>Cached rows: core-seconds of gathering one into a worker’s scratch and of building and writing one, both per payload byte.</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-enum-Object.html"><code>Object</code></a></td><td>A cached object.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-enum-PlanObjective.html"><code>PlanObjective</code></a></td><td>What a compilation minimizes.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-enum-RowPolicy.html"><code>RowPolicy</code></a></td><td>Row selection of page+row compilations.</td></tr></tbody></table><h3 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-constant-DEFAULT_CHUNK.html"><code>DEFAULT_CHUNK</code></a></td><td>Default compilation chunk in accesses.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-constant-DEFAULT_COMPILE_THREADS.html"><code>DEFAULT_COMPILE_THREADS</code></a></td><td>Default compiler threads: a fixed count, not derived from the machine.</td></tr></tbody></table><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-fn-access_fingerprint.html"><code>access_fingerprint</code></a></td><td>Identity of an access sequence, checked before a plan is used.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-fn-default_distance.html"><code>default_distance</code></a></td><td>Default execution window in accesses for a worker count and in-flight depth: four times the accesses in flight.</td></tr></tbody></table><h2 id="default-model-api" tabindex="-1">Default-model API <a class="header-anchor" href="#default-model-api" aria-label="Permalink to &quot;Default-model API&quot;">​</a></h2><h3 id="structs-1" tabindex="-1">Structs <a class="header-anchor" href="#structs-1" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-struct-Host.html"><code>Host</code></a></td><td>The host’s worker costs and memory bandwidth.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-struct-Storage.html"><code>Storage</code></a></td><td>Device rates of a tier and its per-request worker cost.</td></tr></tbody></table><h3 id="enums-1" tabindex="-1">Enums <a class="header-anchor" href="#enums-1" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-enum-Tier.html"><code>Tier</code></a></td><td>A class of storage, for its default device rates.</td></tr></tbody></table><h3 id="constants-1" tabindex="-1">Constants <a class="header-anchor" href="#constants-1" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-constant-BUCKET.html"><code>BUCKET</code></a></td><td>Accesses per priced window.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-constant-HOST.html"><code>HOST</code></a></td><td>Worker costs of the reference machine, in core-seconds.</td></tr></tbody></table><h3 id="functions-1" tabindex="-1">Functions <a class="header-anchor" href="#functions-1" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-fn-builtin.html"><code>builtin</code></a></td><td>The built-in dense output.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-fn-process.html"><code>process</code></a></td><td>A process function nothing was measured for.</td></tr><tr><td><a href="/CellPack/rust/api/generated-opt-defaults-fn-storage.html"><code>storage</code></a></td><td>The stored rates of a tier: sustained random reads, and the loader’s per-request cost measured on the reference machine.</td></tr></tbody></table>`,51))])}const P=d(l,[["render",h]]);export{y as __pageData,P as default};
